create view [dbo].[sanaddar_sub] as SELECT     PGET_HED.MOLAH, PAY_GETD.DATE_S, PAY_GETD.SHOBEH, PAY_GETD.MABL AS mabld, PAY_GETD.N_HESAB, PGET_LST.*, CUST_HESAB.hes,                      CUST_HESAB.NAME , TCOD_BANKS.NAMES, PGET_HED.IDK FROM         PGET_HED INNER JOIN                      PGET_LST ON PGET_HED.ID = PGET_LST.ID AND PGET_HED.DATE = PGET_LST.DATE INNER JOIN                      PAY_GETD ON PGET_LST.N_SERI = PAY_GETD.N_SERI AND PGET_LST.BANK = PAY_GETD.BANK INNER JOIN                      CUST_HESAB ON PGET_LST.FHES = CUST_HESAB.hes LEFT OUTER JOIN                      TCOD_BANKS ON PAY_GETD.BANK = TCOD_BANKS.CODE WHERE (PGET_LST.NO_AM = 1)    UNION SELECT     dbo.PGET_HED.MOLAH, dbo.PAY_GETp.DATE_S, dbo.PAY_GETp.SHOBEH, dbo.PAY_GETp.MABL AS mabld, dbo.PAY_GETp.N_HESAB,                      dbo.PGET_LST.*, dbo.CUST_HESAB.hes, dbo.CUST_HESAB.NAME, dbo.TCOD_BANKS.NAMES, dbo.PGET_HED.IDK FROM         dbo.TCOD_BANKS INNER JOIN dbo.PAY_GETp ON dbo.TCOD_BANKS.CODE = dbo.PAY_GETp.BANK RIGHT OUTER JOIN                      dbo.PGET_HED INNER JOIN                      dbo.PGET_LST ON dbo.PGET_HED.ID = dbo.PGET_LST.ID AND dbo.PGET_HED.DATE = dbo.PGET_LST.DATE INNER JOIN                      dbo.CUST_HESAB ON dbo.PGET_LST.FHES = dbo.CUST_HESAB.hes ON dbo.PAY_GETp.BANK = dbo.PGET_LST.BANK AND                      dbo.PAY_GETp.N_SERI = dbo.PGET_LST.N_SERI WHERE (dbo.PGET_LST.NO_AM = 1) And (dbo.PGET_LST.NAHVA > 3)
